xml.Script:
        clBlue   := '0055EE';
        clGreen  := '00AA00';
        clRed    := 'EE0000';
        clPurple := '8800BB';
        clYellow := 'FFEE00';
        clWhite  := 'FFFFFF';
        clOrange := 'FF6600';
        clRose   := 'EE77AA';

        R := 0.6;

        H := R * sin(Pi / 9);
        sAngle := 2 * Pi / 6;
        for i := 0 to 5 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
        end;
        for i := 0 to 2 do begin
            ax[i] := sin(sAngle * (2 * i + 0.5));
            ay[i] := cos(sAngle * (2 * i + 0.5));
        end;

        D0 := R * 0.69;
        D1 := R * 0.52;
        D2 := H / 3;
        DCut := R * 0.75;
